#!/usr/bin/env python3
"""Assemble a local review artifact from synthetic measured evidence; never publish it."""
import argparse,hashlib,html,json,shutil
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);p.add_argument('--source',required=True);p.add_argument('--status',choices=['verifying','ready'],default='verifying');p.add_argument('--ci',required=True);a=p.parse_args()
root=Path(__file__).resolve().parents[1];out=Path(a.output).resolve();out.mkdir(parents=True,exist_ok=True)
images=[]
for width in [320,1440]:
 name=f'independent-theme-top-{width}.png';source=root/'work/browser-evidence'/name
 if source.exists():shutil.copyfile(source,out/name);images.append((name,hashlib.sha256(source.read_bytes()).hexdigest()))
for name in ['m8-system-uncached.json','m8-system-cached.json','m8-cluster-migration-release-profile.json']:
 source=root/'docs/evidence'/name
 if source.exists():shutil.copyfile(source,out/name)
status='Ready for review' if a.status=='ready' else 'Final verification in progress'
items=[('Migration','Offline WXR assessment; exact preview/private fresh-target packages; selected core, ACF, SEO, Elementor text and WPForms definitions. Unsupported source data remains explicit and recoverable.'),('Business and access','Suppressed contacts, disabled policies, draft ordered courses and unpublished physical catalog. PMPro holds source publication/media pending access review. No imported consent, grants, progress or financial settlement.'),('Integrations','Owner grants/revocation, versioned draft/read API, atomic bounded content events and independently operated HMAC webhooks with replay reconciliation and receiver deduplication.'),('Local AI and themes','Real separately operated Ollama/Qwen content/layout proposals; native independent cardless theme, explicit validation/publication and responsive measurements. No general AI quality or complete Elementor parity claim.')]
rows=''.join(f'<tr><th>{html.escape(k)}</th><td>{html.escape(v)}</td></tr>' for k,v in items)
imgs=''.join(f'<figure><img src="{name}" alt="Actual independent theme at {name.split("-")[-1].split(".")[0]} CSS pixels"><figcaption>{name} · SHA-256 {digest}</figcaption></figure>' for name,digest in images)
doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>wpalt M8 review</title><style>body{{max-width:1080px;margin:0 auto;padding:40px 24px;background:#f8f6f1;color:#242b27;font:16px/1.65 system-ui,sans-serif}}h1{{font:600 clamp(30px,6vw,48px)/1.15 Georgia,serif}}h2{{margin-top:48px;font-size:24px}}a{{color:#315b48}}p{{max-width:76ch}}table{{border-collapse:collapse;width:100%}}td,th{{text-align:left;vertical-align:top;padding:18px 0;border-top:1px solid #bfc8c0}}th{{width:23%;padding-right:24px}}code,figcaption{{overflow-wrap:anywhere}}img{{max-width:100%;height:auto;border:1px solid #bfc8c0}}figure{{margin:28px 0}}figure:first-of-type img{{max-width:320px}}figcaption{{font-size:13px;color:#4d5850}}@media(max-width:600px){{table,tbody,tr,td,th{{display:block}}th{{width:auto;border:0;padding-bottom:0}}}}:focus-visible{{outline:3px solid #315b48;outline-offset:3px}}</style><main><p>wpalt · M8 · {status}</p><h1>A migratable, locally owned platform</h1><p>Source <code>{html.escape(a.source)}</code>. <a href="https://github.com/NaxAlpha/wpalt/pull/14">Pull request #14</a> · <a href="{html.escape(a.ci)}">Exact-source verification run</a>. Review/merge are separate decisions.</p><table>{rows}</table><h2>What to verify</h2><ol><li>Preview a synthetic source, change it and verify the stale plan fails; recover privately into a fresh target and reject an occupied retry.</li><li>Inspect suppressed contacts, disabled access and draft lessons/forms. Explicitly activate an imported catalog, check out without inferred payment, record a native owner receipt and recover its stock/financial graph.</li><li>Issue/revoke a grant; verify stale writes and published-content edits fail. Fail and retry signed delivery, preserving one event identity and a private durable checkpoint.</li><li>Review a private local AI proposal; create a draft without overwriting source. Validate/import a theme as draft, publish/activate deliberately and inspect keyboard/mobile/text spacing.</li></ol><p>86 native Rust cases and eight pipeline safety fixtures are inventory, not coverage percentages. Real PostgreSQL, source-plugin comparisons, cumulative browsers and exact-source clean archive remain mandatory delivery gates. The status above must be checked against the linked run.</p><h2>Resource evidence</h2><p>Baseline optimized macOS sample with 1,001 posts: 27.1 MB executable, about 41.8 MB ready resident memory, 51.6–61.9 MB after load, 20.4–20.6 MB site files including WAL. Startup 121–129 ms. Cached home p95 0.316 ms at concurrency 1 / 2.886 ms at 10. These localhost snapshots exclude optional AI models, build caches and reference installations; they are not peak memory or production capacity guarantees.</p><p><a href="m8-system-uncached.json">Uncached raw report</a> · <a href="m8-system-cached.json">Cached raw report</a> · <a href="m8-cluster-migration-release-profile.json">Cluster projection report</a>. Exact executable hashes and conditions are in each report.</p><h2>Actual viewport captures</h2><p>Independent native theme with synthetic content. Automated geometry/accessibility samples complement human inspection; no whole-product conformance or aesthetic score is claimed.</p>{imgs}<h2>Scope limits</h2><p>No PHP plugin/theme execution, universal plugin database conversion, complete Elementor widget/style/runtime/pixel parity, automatic consent or settlement, raw CSS/JS loader, or exactly-once remote delivery. Original private source exports remain necessary. M9 distributed execution/upgrade work remains separate.</p></main></html>'''
(out/'index.html').write_text(doc);(out/'manifest.json').write_text(json.dumps({'source':a.source,'status':a.status,'ci':a.ci,'captures':dict(images)},indent=2)+'\n');print(out/'index.html')
